export const CANVAS_ACTION_MARKER = '<<<CANVAS_ACTION>>>';

export type Actor = 'user' | 'agent';

export type LayerType = 'raster' | 'vector' | 'ai-generated';

/**
 * A layer stores exactly one kind of content:
 * - `fabric`: a serialized Fabric.js object produced by the brush tool.
 * - `svg`: markup generated by the AI agent.
 *
 * The daemon persists this value as JSON in `layers.content`.
 */
export type LayerContent =
  | { kind: 'fabric'; json: string }
  | { kind: 'svg'; svg: string };

export interface LayerMetadata {
  createdBy: Actor;
  createdAt: number;
  prompt?: string;
}

export interface Layer {
  id: string;
  canvasId: string;
  name: string;
  type: LayerType;
  zIndex: number;
  visible: boolean;
  opacity: number;
  content: LayerContent;
  metadata: LayerMetadata;
  createdAt: number;
}

export interface Canvas {
  id: string;
  name: string;
  width: number;
  height: number;
  backgroundColor: string;
  revision: number;
  createdAt: number;
  updatedAt: number;
}

export interface CanvasHistoryState {
  canUndo: boolean;
  canRedo: boolean;
}

export interface CanvasState extends Canvas {
  layers: Layer[];
}

export interface CanvasDocument extends CanvasState {
  history: CanvasHistoryState;
}

export interface CreateLayerInput {
  name: string;
  type: LayerType;
  content: LayerContent;
  visible?: boolean;
  opacity?: number;
  metadata?: Partial<LayerMetadata>;
}

export interface UpdateLayerPatch {
  name?: string;
  visible?: boolean;
  opacity?: number;
  content?: LayerContent;
}

export type PaintAction =
  | { type: 'canvas_create_layer'; layer: CreateLayerInput }
  | { type: 'canvas_update_layer'; layerId: string; patch: UpdateLayerPatch }
  | { type: 'canvas_delete_layer'; layerId: string };

export interface ApplyActionRequest {
  actor: Actor;
  action: PaintAction;
  expectedRevision?: number;
}

export interface HistoryRequest {
  expectedRevision?: number;
}

export interface SnapshotChangedEvent {
  type: 'snapshot_changed';
  canvasId: string;
  revision: number;
}

export interface CreateCanvasRequest {
  name?: string;
  width?: number;
  height?: number;
  backgroundColor?: string;
}

export interface AiChatRequest {
  canvasId?: string;
  message: string;
}

/**
 * One frame of the `POST /paint/ai/chat` SSE stream. Frames are partial: each
 * frame carries exactly one of the optional members.
 */
export interface StreamPayload {
  delta?: unknown;
  done?: unknown;
  error?: { code?: unknown; message?: unknown };
  /** Progress notification for the pending reply; `label` is UI copy. */
  step?: { id: string; label: string };
  layerCreated?: { id: string; name: string };
}

export interface ApiErrorBody {
  error: {
    code: string;
    message: string;
  };
}

export const LOG_LEVELS = ['debug', 'info', 'warn', 'error'] as const;

export type LogLevel = (typeof LOG_LEVELS)[number];

export const LOG_CATEGORIES = [
  'codex-runner',
  'ai-chat',
  'canvas-action',
  'http',
  'sse',
  'system',
] as const;

export type LogCategory = (typeof LOG_CATEGORIES)[number];

/**
 * One structured observability record. A record either describes a finished
 * span (`durationMs` set) or a point event emitted inside a span.
 */
export interface AgentLog {
  id: number;
  traceId: string | null;
  spanId: string | null;
  parentId: string | null;
  timestamp: number;
  level: LogLevel;
  category: LogCategory;
  message: string;
  payload: unknown;
  durationMs: number | null;
  error: string | null;
  canvasId: string | null;
  revision: number | null;
  actor: Actor | null;
}

export interface AgentLogPage {
  items: AgentLog[];
  total: number;
  limit: number;
  offset: number;
}

export interface AgentTraceNode {
  log: AgentLog;
  children: AgentTraceNode[];
}

export interface AgentTrace {
  traceId: string;
  roots: AgentTraceNode[];
}

export interface MonitorCategoryStats {
  category: LogCategory;
  count: number;
  errorCount: number;
}

export interface MonitorStats {
  windowMs: number;
  totalLogs: number;
  /** Every error-level record in the window, across all categories. */
  errorCount: number;
  /** Failed HTTP request ratio; `null` when the window has no HTTP requests. */
  errorRate: number | null;
  requestCount: number;
  requestsPerSecond: number;
  /** HTTP requests that ended in a server failure (5xx, logged at `error`). */
  httpFailureCount: number;
  /** HTTP requests that ended in a client conflict (4xx, logged at `warn`). */
  httpConflictCount: number;
  /** Mean duration of HTTP requests that recorded a duration. */
  avgDurationMs: number;
  /** Completed AI chats excluding user cancellations (the success denominator). */
  aiChatCount: number;
  /** Completed AI chats at info level; aborted chats do not count as success. */
  aiChatSuccessCount: number;
  /** Chats the user cancelled; kept out of the success rate and shown separately. */
  aiChatAbortedCount: number;
  /** `null` until five non-aborted chats completed, so small samples read as unknown. */
  aiChatSuccessRate: number | null;
  categoryCounts: MonitorCategoryStats[];
}
